<script setup lang="ts">import{ref,onMounted}from 'vue';import{useRoute,useRouter}from 'vue-router';import{lab,load}from '../stores/research';import{canEdit}from '../stores/auth';import{create}from '../api/runs';import{useTask}from '../hooks/useTask';import PageHeading from '../components/common/PageHeading.vue';import ErrorNotice from '../components/common/ErrorNotice.vue';const route=useRoute(),router=useRouter(),survey=ref(Number(route.query.survey)||0),a=ref(0),b=ref(0),perms=ref(499),seed=ref(157),name=ref('浮标圆周复核 · '+new Date().toLocaleTimeString()),{error,busy,execute}=useTask();onMounted(()=>execute(async()=>{await load();survey.value=survey.value||lab.surveys[0]?.id||0;a.value=lab.moorings[0]?.id||0;b.value=lab.moorings[1]?.id||0}));function submit(){execute(async()=>{const r=await create({name:name.value,survey_id:survey.value,mooring_a_id:a.value,mooring_b_id:b.value,permutations:perms.value,seed:seed.value});router.push('/results?run='+r.id)})}</script><template><PageHeading index="03" title="先约定比较，再交换标签。" text="同一调查期两座浮标；圆周拟合与energy差异来自Python真实计算，置换保留各组样本量。"/><ErrorNotice :message="error" @retry="execute(load)"/><div class="configure-grid"><form @submit.prevent="submit"><label>研究名称<input v-model="name" required minlength="3" maxlength="160" :disabled="!canEdit"></label><label>调查期<select aria-label="调查期" v-model="survey" :disabled="!canEdit"><option v-for="s in lab.surveys" :value="s.id">{{s.name}}</option></select></label><div class="paired-inputs"><label>A组浮标<select aria-label="A组浮标" v-model="a" :disabled="!canEdit"><option v-for="m in lab.moorings" :value="m.id">{{m.name}}</option></select></label><label>B组浮标<select aria-label="B组浮标" v-model="b" :disabled="!canEdit"><option v-for="m in lab.moorings" :value="m.id">{{m.name}}</option></select></label></div><div class="paired-inputs"><label>标签置换次数<input v-model.number="perms" type="number" min="99" max="999" step="100" :disabled="!canEdit"></label><label>随机seed<input v-model.number="seed" type="number" min="0" max="2147483647" :disabled="!canEdit"></label></div><button v-if="canEdit" class="primary" :disabled="busy||a===b">排队计算圆周研究 →</button><p v-else class="margin-note">当前角色只读，可阅读研究和获批导出。</p></form><aside class="method-margin"><p class="eyebrow">METHOD BEFORE RESULT</p><h2>一个角度，<br>两个分布问题。</h2><ol><li>用单位向量计算均值方向和合向量R；弱合向量不强给方向。</li><li>拟合von Mises集中度，仅描述一个单峰圆周分布；双峰可能被一阶均值遮住。</li><li>energy基于弦距离比较整体分布，可反映位置和集中度差异。</li><li>标签置换要求独立、可交换观测；真实连续浮标数据常有自相关，须另行处理。</li></ol><p>不同组不允许重复引用；每组2–250条，空组会形成明确失败任务。p值最小为1/(B+1)，不作显著性自动行动。</p></aside></div></template>
